INSERT INTO `courses` (`id`, `name`, `description`, `duration`, `fee`, `icon`, `display_order`, `status`, `created_at`, `updated_at`) VALUES
(4, 'Matric Programs (9th & 10th)', 'Complete matriculation preparation in Science, Arts, and Computer Science groups. Our comprehensive program covers all subjects with experienced teachers and modern teaching methods.', '2 Years', 5000.00, 'fa-graduation-cap', 1, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(5, 'Intermediate - Pre-Engineering', 'FSc Pre-Engineering program for students aspiring to pursue engineering careers. Covers Physics, Chemistry, Mathematics with practical lab work and concept-based learning.', '2 Years', 6000.00, 'fa-book-open', 2, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(6, 'Intermediate - Pre-Medical', 'FSc Pre-Medical program designed for future medical professionals. Comprehensive coverage of Biology, Chemistry, Physics with focus on MDCAT preparation.', '2 Years', 6000.00, 'fa-flask', 3, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(7, 'Intermediate - Computer Science', 'ICS program combining mathematics with computer science. Perfect for students interested in IT, software development, and technology fields.', '2 Years', 6000.00, 'fa-laptop', 4, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(8, 'ECAT Preparation', 'Intensive preparation course for Engineering College Admission Test. Covers all test patterns, practice questions, and proven strategies for success.', '3-6 Months', 8000.00, 'fa-pencil-alt', 5, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(9, 'MDCAT Preparation', 'Comprehensive Medical and Dental College Admission Test preparation. Expert faculty, extensive practice tests, and personalized guidance.', '3-6 Months', 8000.00, 'fa-stethoscope', 6, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(10, 'Computer Programming', 'Learn modern programming languages including C++, Python, Java, and web development. Hands-on projects and practical coding experience.', '6 Months', 4000.00, 'fa-laptop-code', 7, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(11, 'Web Development', 'Complete web development course covering HTML, CSS, JavaScript, PHP, and MySQL. Build real-world websites and applications.', '6 Months', 5000.00, 'fa-globe', 8, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(12, 'Spoken English', 'Improve your English communication skills with our interactive spoken English course. Focus on fluency, pronunciation, and confidence.', '3 Months', 3000.00, 'fa-comments', 9, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(13, 'IELTS Preparation', 'Comprehensive IELTS test preparation covering all modules: Listening, Reading, Writing, and Speaking. Expert guidance and practice tests.', '2-3 Months', 7000.00, 'fa-plane', 10, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(14, 'Advanced Mathematics', 'Advanced mathematics courses for competitive exams and higher studies. Covers Calculus, Algebra, Trigonometry, and more.', '6 Months', 4000.00, 'fa-calculator', 11, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13'),
(15, 'Physics & Chemistry', 'In-depth Physics and Chemistry courses with practical demonstrations and problem-solving techniques for all levels.', '6 Months', 4500.00, 'fa-atom', 12, 'active', '2026-09-11 09:39:13', '2026-09-11 09:39:13');
