INSERT INTO `faqs` (`id`, `question`, `answer`, `display_order`, `status`, `created_at`) VALUES
(1, 'What are the admission requirements?', 'Admission requirements vary by program. Generally, you need previous educational certificates, CNIC/B-Form, photographs, and the admission fee. Visit our Courses page for detailed requirements.', 1, 'active', '2026-09-11 10:20:15'),
(2, 'How can I apply for admission?', 'You can apply online through our Admission page or visit our campus in person. Fill out the application form, submit required documents, and pay the admission fee to complete the process.', 2, 'active', '2026-09-11 10:20:15'),
(3, 'What is the fee structure?', 'Our fee structure is transparent and affordable. Fees vary by program, starting from Rs. 3,000/month for short courses to Rs. 8,000/month for entry test preparation. Check our Admission page for complete details.', 3, 'active', '2026-09-11 10:20:15'),
(4, 'Do you offer scholarships?', 'Yes, we offer merit-based scholarships and financial assistance to deserving students. Contact our admission office for more information about scholarship opportunities.', 4, 'active', '2026-09-11 10:20:15'),
(5, 'How can I contact a specific teacher?', 'You can visit our campus during working hours or call our main office. We will connect you with the appropriate faculty member or department.', 5, 'active', '2026-09-11 10:20:15');
