(1, 'images/hero/slide_1789185196_6aa4ccac14f2b.jpg', 'Welcome to Shaheen Public High School', 'Empowering students with quality education', '#ffffff', 1, 'active', '2025-12-26 10:06:59', '2026-09-12 09:40:34'),
(2, 'images/hero/slide_1789185225_6aa4ccc97fb75.jpg', 'Excellence in Education', 'Building tomorrow\'s leaders today', '#ffffff', 2, 'active', '2025-12-26 10:06:59', '2026-09-12 09:40:35'),
