INSERT INTO `leadership` (`id`, `name`, `designation`, `role_title`, `photo`, `signature`, `message`, `display_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Chaudhary Matloob Hussain', 'Director and Principal', 'Director', 'images/leadership/leader_1766747201_1692.PNG', '', 'Education is the foundation of progress and a successful future. At Shaheen Public High School, we are committed to providing quality education that nurtures academic excellence, strong character, and lifelong learning.\r\n\r\nOur focus is to create a positive and disciplined environment where students are encouraged to think critically, grow confidently, and achieve their full potential. Through dedicated teachers, modern teaching methods, and strong values, we aim to prepare our students to become responsible citizens and future leaders.\r\n\r\nTogether, we strive to build a brighter tomorrow.', 1, 'active', '2025-12-26 07:56:01', '2025-12-26 11:09:49'),
(2, 'Saman Talib', 'Vice Principal', 'Head of Academics', 'images/leadership/leader_1766747606_8242.jpg', '', 'At Shaheen Public High School, we are committed to maintaining a balanced and nurturing educational environment where discipline, respect, and academic growth go hand in hand.\r\n\r\nOur aim is to support students in developing confidence, responsibility, and a love for learning. With the cooperation of teachers and parents, we strive to guide our students toward becoming well-rounded individuals who are prepared for future challenges.\r\n\r\nTogether, we work to ensure excellence in education and character building.', 2, 'active', '2025-12-26 07:56:01', '2025-12-26 11:13:26'),
(3, 'Founder Name', 'Founder & Chairman', 'Founder Message', 'images/leadership/founder.jpg', NULL, 'When we established this institution, our mission was clear - to provide quality education accessible to all, nurturing young minds to become future leaders of our nation.', 3, 'inactive', '2025-12-26 07:56:01', '2025-12-26 08:19:34');
INSERT INTO `news` (`id`, `title`, `content`, `image`, `author`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Shaheen Public High School Achieves Excellent Board Results', 'We are proud to announce that our students have achieved outstanding results in this year\'s board examinations, with a pass percentage of over 95%. Special congratulations to our top position holders who brought pride to the school through their hard work and dedication.', NULL, 'Admin Office', 'active', '2026-09-11 06:46:34', '2026-09-11 06:46:34'),
(2, 'New Computer Lab Inaugurated', 'To support our digital learning initiatives, a new state-of-the-art computer lab has been inaugurated at the campus, featuring modern systems and high-speed internet access for students to enhance their IT skills.', NULL, 'Admin Office', 'active', '2026-09-11 06:46:34', '2026-09-11 06:46:34'),
(3, 'Admissions Open for New Academic Session', 'Shaheen Public High School is now accepting admissions for Matric and Intermediate programs for the upcoming academic session. Interested students and parents are encouraged to visit the campus or apply online.', NULL, 'Admission Office', 'active', '2026-09-11 06:46:34', '2026-09-11 06:46:34'),
(4, 'School Wins Inter-School Debate Competition', 'Our debate team secured first position in the regional inter-school debate competition, demonstrating exceptional public speaking and critical thinking skills. Congratulations to the entire team and their mentors.', NULL, 'Admin Office', 'active', '2026-09-11 06:46:34', '2026-09-11 06:46:34');
